    /// <summary>
    /// Synchronous drain loop. Dequeues activations, dispatches one step per goal,
    /// tracks reductions/suspensions/failures, applies infrastructure-goal filtering
    /// (spec §3.4), and returns a <see cref="DrainResult"/> with the final
    /// <see cref="ExecutionStatus"/> and blocking readers (spec §8.4).
    /// Carry-forward of
    /// <c>rf-dart-central-drain-loop-with-closure-capture-and-status-classification-to-csharp-while-loop-with-display-class</c>.
    /// </summary>
    public DrainResult DrainWithStatus(
        int maxCycles = 1000,
        bool debug = false,
        bool showBindings = true,
        bool debugOutput = false)
    {
        var ran = new List<int>();
        var suspendedGoals = new Dictionary<int, string>();
        var cycles = 0;
        var hasFailed = false;

        while (Rt.Gq.Length > 0 && cycles < maxCycles)
        {
            var act = Rt.Gq.Dequeue();
            if (act == null) break;

            ran.Add(act.Value.Id);

            var env = Rt.GetGoalEnv(act.Value.Id);
            var program = Rt.GetGoalProgram(act.Value.Id);

            // Runner lookup: own Runners table first, then Rt.Runners fallback.
            // Sentinel for null program key:
            //   Dart null-key → RuntimeKeys.DefaultProgramKey
            //   (Dictionary<object?,...>.Add throws on literal null — see convspec nuance).
            var key = program ?? RuntimeKeys.DefaultProgramKey;
            BytecodeRunner? runner = Runners.TryGetValue(key, out var r1) ? r1 : null;
            runner ??= Rt.Runners.TryGetValue(key, out var r2) ? r2 : null;

            if (runner == null)
                throw new InvalidOperationException(
                    $"No runner found for program {program} for goal {act.Value.Id}");

            // Scan Labels to find the procedure name at the current PC.
            var procName = "?";
            foreach (var entry in runner.Program.Labels)
            {
                if (entry.Value == act.Value.Pc)
                {
                    procName = entry.Key;
                    break;
                }
            }

            var goalStr = FormatGoal(act.Value.Id, procName, env);
            var isQueryWrapper = procName.StartsWith("query__", StringComparison.Ordinal);

            // Track whether this goal reduced (committed a clause). Set true by the
            // onReduction callback below; distinguishes terminated-with-reduction
            // (success) from terminated-without-reduction (failure) — see the
            // RunResult.Terminated arm. The C# compiler captures this local by
            // reference in the lambda's display class, so the mutation is visible
            // here after RunWithStatus returns. (Mirrors scheduler.dart; the wiring
            // was stubbed out while runner.cs was a placeholder and is restored now
            // that the full runner.cs invokes onReduction at its Commit arms.)
            var hadReduction = false;

            var moduleContext = Rt.GetGoalModuleContext(act.Value.Id);

            // Full RunnerContext mirroring scheduler.dart's named-arg form. The
            // onReduction callback is REQUIRED: without it hadReduction stays false
            // even when the goal reduces, misclassifying success as failure.
            var cx = new RunnerContext(
                rt:            Rt,
                goalId:        act.Value.Id,
                kappa:         act.Value.Pc,
                env:           env,
                goalHead:      goalStr,
                goalProcName:  procName,
                showBindings:  showBindings,
                debugOutput:   debugOutput,
                moduleContext: moduleContext,
                termFormatter: (term, markReaders) => FormatTerm(term, markReaders),
                onReduction:   (goalId, head, body) =>
                {
                    // Query-wrapper goals reduce silently (no user-visible trace).
                    if (head.Contains("query__", StringComparison.Ordinal))
                    {
                        hadReduction = true;
                        suspendedGoals.Remove(goalId);
                        return;
                    }
                    // Print the reduction (head :- body) at Commit when tracing.
                    if (debug)
                    {
                        var cleanHead = StripArityRegex.Replace(head, m => $"{m.Groups[1].Value}(");
                        var cleanBody = StripArityRegex.Replace(body, m => $"{m.Groups[1].Value}(");
                        Trace($"{cleanHead} :- {cleanBody}");
                    }
                    hadReduction = true;
                    suspendedGoals.Remove(goalId);
                });
            var result = runner.RunWithStatus(cx);

            if (result == RunResult.Suspended)
            {
                suspendedGoals[act.Value.Id] = goalStr;
                if (debug && !hadReduction && !isQueryWrapper)
                {
                    var cleanGoal = StripArityRegex.Replace(goalStr,
                        m => $"{m.Groups[1].Value}(");
                    Trace($"{cleanGoal} → suspended");
                }
            }
            else if (result == RunResult.Terminated)
            {
                if (!hadReduction && !isQueryWrapper)
                {
                    if (debug)
                    {
                        var cleanGoal = StripArityRegex.Replace(goalStr,
                            m => $"{m.Groups[1].Value}(");
                        Trace($"{cleanGoal} → failed");
                    }
                    hasFailed = true;
                    suspendedGoals.Remove(act.Value.Id);
                    break;
                }
                else
                {
                    suspendedGoals.Remove(act.Value.Id);
                }
            }

            cycles++;
        }

        // Filter out infrastructure goals (spec §3.4).
        // Dart cascade `Map.from(suspendedGoals)..removeWhere(...)` →
        // LINQ Where+ToDictionary (yields fresh non-aliased dictionary).
        var userSuspendedGoals = suspendedGoals
            .Where(kv => !Rt.InfrastructureGoalIds.Contains(kv.Key))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        ExecutionStatus status;
        if (hasFailed)
            status = ExecutionStatus.Failed;
        else if (userSuspendedGoals.Count > 0)
            status = ExecutionStatus.Suspended;
        else
            status = ExecutionStatus.Succeeded;

        // Strip /arity suffixes from suspended goal strings for standard GLP display syntax.
        var suspendedList = userSuspendedGoals.Values
            .Select(g => StripArityRegex.Replace(g, m => $"{m.Groups[1].Value}("))
            .ToList();

        // Collect blocking readers from the runtime's suspension index (spec §8.4).
        // rt.suspended maps reader addr → Set<GoalRef> of goals blocked on that reader.
        var blockingReaders = status == ExecutionStatus.Suspended
            ? new HashSet<int>(Rt.Suspended.Keys)
            : new HashSet<int>();

        return new DrainResult(ran, status, suspendedList, blockingReaders);
    }

