    /// <summary>
    /// Async drain that waits for pending timers to fire.
    /// Outer loop calls the synchronous <see cref="DrainWithStatus"/> then
    /// <c>await Task.Delay(10)</c> until no more pending timers or the goal queue
    /// is re-populated.
    /// No <c>CancellationToken</c> (FR-013 — escalate if needed);
    /// no <c>ConfigureAwait(false)</c> (single-owning-context invariant inherited
    /// from heap_fcp.dart.md escalations[0]).
    /// Carry-forward of <c>rf-dart-future-delayed-to-csharp-task-delay</c>.
    /// </summary>
    public async Task<DrainResult> DrainAsyncWithStatus(
        int maxCycles = 1000,
        bool debug = false,
        bool showBindings = true,
        bool debugOutput = false)
    {
        var ran = new List<int>();
        var totalCycles = 0;
        var lastStatus = ExecutionStatus.Succeeded;
        IReadOnlyList<string> lastSuspended = Array.Empty<string>();
        IReadOnlySet<int> lastBlockingReaders = new HashSet<int>();

        while (totalCycles < maxCycles)
        {
            var result = DrainWithStatus(
                maxCycles - totalCycles,
                debug,
                showBindings,
                debugOutput);

            ran.AddRange(result.GoalsRan);
            totalCycles += result.GoalsRan.Count;
            lastStatus = result.Status;
            lastSuspended = result.SuspendedGoals;
            lastBlockingReaders = result.BlockingReaders;

            if (lastStatus == ExecutionStatus.Failed)
                break;

            if (Rt.PendingTimers <= 0)
                break;

            // Dart `print(...)` → Console.WriteLine (carry-forward rf-dart-print-to-csharp-console-writeline).
            if (debugOutput)
                Console.WriteLine($"[DEBUG] Waiting for {Rt.PendingTimers} pending timer(s)...");

            // Poll with small delay until queue has work or no more pending timers.
            // Dart `await Future.delayed(Duration(milliseconds: 10))` → `await Task.Delay(10)`.
            while (Rt.Gq.Length == 0 && Rt.PendingTimers > 0 && totalCycles < maxCycles)
                await Task.Delay(10);
        }

        return new DrainResult(ran, lastStatus, lastSuspended, lastBlockingReaders);
    }

